SELECT
    S.*
FROM
    (
    
    SELECT 
    'PMPI' ORGAO,
    TA.CODIGO,
    EE.ID_ESOCIAL_EVENTO,
    EE.CHAVE_VOBYS,
    CASE
        WHEN EE.STATUS_VOBYS = 'P' THEN 'Pendente'
        WHEN EE.STATUS_VOBYS = 'A' THEN 'Assinado'
        WHEN EE.STATUS_VOBYS = 'T' THEN 'Transmitido'
        WHEN EE.STATUS_VOBYS = 'E' THEN 'Erro'
        WHEN EE.STATUS_VOBYS = 'R' THEN 'Aprovado'
        WHEN EE.STATUS_VOBYS = 'G' THEN 'Aguardando Processamento'
        WHEN EE.STATUS_VOBYS = 'M' THEN 'Em preenchimento'
        WHEN EE.STATUS_VOBYS = 'X' THEN 'Excluido'
    END STATUS,
    EE.RECIBO,
    EA.VALOR_ATRIBUTO ATRIBUTO_COD_CATEG,
    EA2.VALOR_ATRIBUTO ATRIBUTO_CPF,
    EO.DESCRICAO DESCRICAO_OCORRENCIA, 
    'https://siape.sead.pi.gov.br/org/pmpi/esocial/envio/eventos/evento/' || EE.ID_ESOCIAL_EVENTO LINK,
    'UPDATE SW_PMPI.ESOCIAL_EVENTO EE SET EE.STATUS_VOBYS = ''R'' WHERE EE.ID_ESOCIAL_EVENTO = ' || EE.ID_ESOCIAL_EVENTO || ';' AS UPDATE_,
    ROW_NUMBER() OVER (PARTITION BY EA.VALOR_ATRIBUTO, EA2.VALOR_ATRIBUTO ORDER BY EE.DATA_CADASTRO DESC) RN,
    EE.DATA_CADASTRO
FROM
    SW_PMPI.ESOCIAL_EVENTO EE
    JOIN SW_PMPI.ESOCIAL_EVENTO_ATRIBUTO EA ON EA.ID_ESOCIAL_EVENTO = EE.ID_ESOCIAL_EVENTO AND EA.NOME_ATRIBUTO = 'codCateg'
    JOIN SW_PMPI.ESOCIAL_EVENTO_ATRIBUTO EA2 ON EA2.ID_ESOCIAL_EVENTO = EE.ID_ESOCIAL_EVENTO AND EA2.NOME_ATRIBUTO = 'cpfTrab'
    JOIN SW_PMPI.ESOCIAL_EVENTO_OCORRENCIA EO ON EO.ID_ESOCIAL_EVENTO = EE.ID_ESOCIAL_EVENTO 
    JOIN SW_PUBLICO.ESB_TIPO_ARQUIVO_ESOCIAL TA ON TA.ID_ESB_TIPO_ARQUIVO_ESOCIAL = EE.ID_ESOCIAL_TIPO_ARQUIVO
WHERE
